'use strict';
// smg360-auth-helper.js
// Playwright helper for SMG 360 authentication.
// Purpose:
// 1. Do NOT hand-build the OAuth authorize URL.
// 2. First reuse the existing 360.smg.com authorizationData cookie if present.
// 3. If no usable cookie exists, navigate to https://360.smg.com and capture the real
//    auth.smg.com/connect/authorize URL generated by the app/runtime.

const TARGET_ORIGIN = 'https://360.smg.com';
const TARGET_URL = 'https://360.smg.com/';
const AUTH_HOST = 'auth.smg.com';
const AUTHORIZE_PATH = '/connect/authorize';
const AUTH_COOKIE_NAME = 'authorizationData';

function safeJsonParse(value) {
  try { return JSON.parse(value); } catch (_) { return null; }
}

function decodeCookieValue(value) {
  if (!value) return value;
  const candidates = [value];
  try { candidates.push(decodeURIComponent(value)); } catch (_) {}
  for (const candidate of candidates) {
    const parsed = safeJsonParse(candidate);
    if (parsed) return parsed;
  }
  return null;
}

async function getAuthorizationDataCookie(context) {
  const cookies = await context.cookies(TARGET_ORIGIN);
  return cookies.find((cookie) => cookie.name === AUTH_COOKIE_NAME) || null;
}

async function getTokensFromAuthorizationDataCookie(context) {
  const cookie = await getAuthorizationDataCookie(context);
  if (!cookie || !cookie.value) return null;
  const parsed = decodeCookieValue(cookie.value);
  if (!parsed) {
    return { cookie, tokens: null, parseError: 'authorizationData cookie exists but could not be parsed as JSON' };
  }
  const accessToken  = parsed.access_token  || parsed.accessToken  || parsed.token       || parsed.AccessToken  || null;
  const refreshToken = parsed.refresh_token || parsed.refreshToken || parsed.RefreshToken || null;
  return { cookie, tokens: { raw: parsed, accessToken, refreshToken } };
}

function isAuthorizeUrl(url) {
  try {
    const parsed = new URL(url);
    return parsed.hostname === AUTH_HOST && parsed.pathname.toLowerCase().includes(AUTHORIZE_PATH);
  } catch (_) { return false; }
}

function extractAuthorizeParams(authorizeUrl) {
  const url = new URL(authorizeUrl);
  const params = {};
  for (const [key, value] of url.searchParams.entries()) params[key] = value;
  return params;
}

async function captureRealAuthorizeUrl(page, options = {}) {
  const timeoutMs = options.timeoutMs || 30000;
  let capturedAuthorizeUrl = null;

  const onRequest  = (request)  => { if (isAuthorizeUrl(request.url()))  capturedAuthorizeUrl = request.url(); };
  const onResponse = (response) => { if (isAuthorizeUrl(response.url())) capturedAuthorizeUrl = response.url(); };

  page.on('request',  onRequest);
  page.on('response', onResponse);

  try {
    await page.goto(TARGET_URL, { waitUntil: 'domcontentloaded', timeout: timeoutMs });
    const start = Date.now();
    while (!capturedAuthorizeUrl && Date.now() - start < timeoutMs) {
      const currentUrl = page.url();
      if (isAuthorizeUrl(currentUrl)) { capturedAuthorizeUrl = currentUrl; break; }
      await page.waitForTimeout(500);
    }
  } finally {
    page.off('request',  onRequest);
    page.off('response', onResponse);
  }

  if (!capturedAuthorizeUrl) return null;
  return { authorizeUrl: capturedAuthorizeUrl, params: extractAuthorizeParams(capturedAuthorizeUrl) };
}

async function getSmg360Auth(page, context, options = {}) {
  // 1. First try existing session cookie.
  let cookieResult = await getTokensFromAuthorizationDataCookie(context);
  if (cookieResult && cookieResult.tokens && cookieResult.tokens.accessToken) {
    return { mode: 'cookie', cookie: cookieResult.cookie, tokens: cookieResult.tokens };
  }

  // 2. No usable cookie. Capture real authorize URL generated by 360.smg.com.
  const captured = await captureRealAuthorizeUrl(page, options);

  // 3. Navigation may have established a cookie even if no authorize URL was caught.
  cookieResult = await getTokensFromAuthorizationDataCookie(context);
  if (cookieResult && cookieResult.tokens && cookieResult.tokens.accessToken) {
    return { mode: 'cookie', cookie: cookieResult.cookie, tokens: cookieResult.tokens };
  }

  if (captured) {
    return { mode: 'authorize_url', authorizeUrl: captured.authorizeUrl, params: captured.params };
  }

  return {
    mode: 'needs_login',
    message: 'No authorizationData cookie found and no auth.smg.com/connect/authorize request was captured. Open https://360.smg.com in a headed browser, log in manually, then rerun.',
  };
}

module.exports = { getSmg360Auth, getTokensFromAuthorizationDataCookie, captureRealAuthorizeUrl, extractAuthorizeParams };
